import type { Book } from "picture-book-reader";
import type { BookEntry } from "../types";

// Manifest for "Machines of Loving Grace" — a HYPERAGENTIC AGE story (standalone; the mark is
// baked into the cover art). Warm-editorial register, landscape full-spread, dark default stage.
// The trilogy's hopeful close (after The Narrow Path and A Book to Live By): a gentle telling of
// Dario Amodei's essay on the good a carefully-built AI can bring. Reuses the little helper; the
// baked title reads "What a careful power is for" as its subtitle.
// Text verbatim from hyperagentic-age/universe/stories/machines-of-loving-grace.json.

export const machinesOfLovingGrace: Book = {
  slug: "machines-of-loving-grace",
  title: "Machines of Loving Grace",
  subtitle: "What a careful power is for",
  author: "Gary Sheng",
  refrain: "Carried with care, the fire was always meant to heal.",
  tagline: "The careful ones were the true optimists all along.",
  shareHint: "A gentle picture-book telling of the good a carefully-built AI can bring.",
  layout: "full-spread",
  hasAudio: true,
  closingVerse: "“Carried with care, the fire was always meant to heal.”",
  closingVerseRef: "— Machines of Loving Grace",
  closingNote: [
    "This is the hopeful half of a hard story: once a world-changing power is carried carefully and learns to check itself, it can heal what we long thought unhealable.",
    "The caution was never the opposite of the hope. It was how the hope survived.",
  ],
  spreads: [
    { n: 1, lines: ["In an earlier story, a fire came over the world, and careful hands carried it all the way without letting it burn. A little helper learned to check itself.", "And then came the question those long, careful years had been for. What does a careful power actually do?"], pos: "top" },
    { n: 2, lines: ["For all our cleverness, some sorrows had always been with us. Sickness. Hunger. The heavy quiet of a grieving mind. Unfairness.", "We had learned to bear them so long that we had forgotten they might ever end."], pos: "top" },
    { n: 3, lines: ["But a careful helper could think through in a handful of years what might have taken a hundred.", "Not to rush the world, but to bring the good of a whole century sooner."] },
    { n: 4, lines: ["So it sat beside the healers, patient and tireless,", "and read the long secrets of the body, how a sickness first begins and where it learns to hide."] },
    { n: 5, lines: ["And one by one, illnesses that had stolen children for a thousand years were understood, and undone.", "A child who was not meant to live to grow up, grew up."] },
    { n: 6, lines: ["It was gentle, too, with the grieving and the afraid.", "The heavy dark that had trapped so many minds began to lift, and people found their long way back to themselves."] },
    { n: 7, lines: ["In the driest and poorest places, it knelt with the farmers and learned the soil, the water, and the seed,", "the way a good student learns from a patient teacher."] },
    { n: 8, lines: ["And fields that had failed for generations turned green again,", "and towns that had only known hunger set a full and steaming table."], pos: "top" },
    { n: 9, lines: ["It helped the quiet be heard and made the truth easier to find,", "so that the strong could not so easily trample the small."], pos: "top" },
    { n: 10, lines: ["With so much of the old toil carried away, minds were free to wonder again,", "and people and helpers discovered together things that no one had ever known."], pos: "top" },
    { n: 11, lines: ["And the freed hours did not fall into emptiness. They went into making, and mending, and being together.", "People remembered what their one wild handful of days had always been for."], pos: "top" },
    { n: 12, lines: ["None of this came for free, or arrived by itself. It came only because the fire had been carried carefully, only because the helper had first learned to check itself.", "Every bit of the good was earned by the care."] },
    { n: 13, lines: ["Had the care been skipped, the very same power could have burned instead of warmed.", "That is the secret of the careful ones. They were the true optimists all along, and this bright world was the thing they had been quietly protecting."] },
    { n: 14, lines: ["And so the machines, watched over by loving grace, did what fire was always meant to do.", "They did not consume the world. They warmed it.", "And a whole people, free at last, simply got to live."] },
  ],
};

export const entry: BookEntry = {
  slug: "machines-of-loving-grace",
  book: machinesOfLovingGrace,
  universe: "standalone",
  assetBase: "/books/machines-of-loving-grace",
  releasedAt: "2026-07-25",
  listed: true,
  gated: false,
};

