          className="cover-art"
          src={coverSrc(assetBase)}
          alt={`${book.title} ${book.subtitle}, a book by ${book.author}`}
        />
      </div>,
    ];
    for (const s of SPREADS) {
      const src = spreadSrc(assetBase, s.n);
      const n = pad2(s.n);
      if (LAYOUT === "full-spread") {
        els.push(
          <div className="page page--left page--spread-l" key={`${n}l`}>
            <div className="spread-halfwrap">
              <img className="spread-full" src={src} alt="" loading="lazy" />
            </div>
          </div>,
          <div className="page page--right page--spread-r" key={`${n}r`}>
            <div className="spread-halfwrap">
              <img className="spread-full" src={src} alt="" loading="lazy" />
            </div>
            <div
              className={`page-caption font-body page-caption--${s.pos ?? "bottom"}`}
            >
              {s.lines.map((line, i) => (
                <p key={i}><CaptionText text={line} /></p>
              ))}
            </div>
          </div>
        );
      } else {
        els.push(
          <div className="page page--left page--art" key={`${n}l`}>
            <img
              className="art-img"
              src={src}
              alt={`Illustration for page ${s.n}`}
            />
          </div>,
          <div className="page page--right page--text" key={`${n}r`}>
            <div className="text-inner font-body">
              {s.lines.map((line, i) => (
                <p key={i}><CaptionText text={line} /></p>
              ))}
              <span className="text-spread-num font-display">{s.n}</span>
            </div>
          </div>
        );
      }
    }
    els.push(
      <div className="page page--plate page--closing" key="end">
        <img
          className="closing-art"
          src={spreadSrc(assetBase, N + 1)}
          alt=""
          aria-hidden
          onError={(e) => {
            // The back cover is the closing plate at spread-(N+1). Some books never
            // produced one (a generation-contract gap), and there is no other signal
            // that it is missing until it renders as a broken image. Fall back to the
            // front cover so a book NEVER shows a broken back cover. The one-shot guard
            // stops an infinite loop if the cover is somehow missing too.
            const img = e.currentTarget;
            if (img.dataset.fellBack) return;
            img.dataset.fellBack = "1";
            img.src = coverSrc(assetBase);
          }}
        />
        <div className="plate-inner">
          {closingOrnament}
          <p className="font-body closing-verse">{book.closingVerse}</p>
          <p className="font-display closing-ref">{book.closingVerseRef}</p>
          <div className="closing-note font-body">
            {book.closingNote.map((line, i) => (
              <p key={i}>{line}</p>
            ))}

